import type { Page } from '@playwright/test';

export async function fillLoginCredentials(page: Page, username: string, password: string) {
    await page.getByTestId("username-field").fill(username);
    await page.getByTestId("password-field").fill(password);
}

export async function submitLoginForm(page: Page) {
    await page.getByTestId("submit-login-button").click();
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await page.waitForURL((u) => !u.pathname.startsWith('/login'));
}

export async function fillRegistrationCredentials(page: Page, username: string, password: string) {
    await page.getByTestId("username-input").fill(username);
    await page.getByTestId("password-input").fill(password);
}
